bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';import pg from 'pg';
const e=process.env;const pool=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,password:readFileSync('/run/secrets/videobot_db_password','utf8').trim(),database:'videobot',max:1,connectionTimeoutMillis:4000});
try{
 const p=await pool.query("SELECT owner_user_id FROM videobot_sticker_packs WHERE status='active' ORDER BY updated_at DESC LIMIT 1");
 if(!p.rowCount)process.exit(85);
 const r=await pool.query("SELECT state->'stickerPending'->>'status' AS status,state->>'screen' AS screen FROM videobot_creator_sessions WHERE owner_user_id=$1",[p.rows[0].owner_user_id]);
 if(!r.rowCount)process.exit(86);
 const s=r.rows[0];
 if(s.status==='needs_reconcile')process.exit(81);
 if(s.status==='in_progress')process.exit(82);
 if(s.status!==null)process.exit(83);
 console.log('STICKER_OWNER_SESSION_CLEAR=PASS');
}catch{process.exitCode=87;}finally{await pool.end();}
NODE
